# Temporal workflow: saga with compensation
from temporalio import workflow, activity

@workflow.defn
class OrderSaga:
    @workflow.run
    async def run(self, order_id: str) -> str:
        reserved = False
        try:
            await workflow.execute_activity(reserve_inventory, order_id)
            reserved = True
            await workflow.execute_activity(charge_payment, order_id)
            await workflow.execute_activity(dispatch_shipment, order_id)
            return "completed"
        except Exception:
            if reserved:
                # Compensating transaction: undo the reservation
                await workflow.execute_activity(release_inventory, order_id)
            raise

