class EventStore:
    def append(self, aggregate_id: str, event: DomainEvent) -> None:
        db.execute(
            "INSERT INTO events (aggregate_id, event_type, payload, occurred_at) "
            "VALUES (%s, %s, %s, NOW())",
            aggregate_id, type(event).__name__, json.dumps(event.to_dict())
        )

    def load(self, aggregate_id: str) -> list[DomainEvent]:
        rows = db.query(
            "SELECT event_type, payload FROM events "
            "WHERE aggregate_id = %s ORDER BY occurred_at",
            aggregate_id
        )
        return [deserialize_event(r['event_type'], r['payload']) for r in rows]

