syntax = "proto3";

message OrderEvent {
  string order_id = 1;   // field tag 1 — never reuse tag numbers
  int32  amount   = 2;
  string currency = 3;   // added in v2; old decoders skip tag 3
  // reserved 4;         // previously removed field — tag reserved to prevent reuse
}

// Old consumer receives new message: ignores tag 3 (currency) safely
// New consumer receives old message: currency defaults to "" (empty string)

# Avro schema evolution — backward-compatible change
# Old schema (v1)
old_schema = {
  "type": "record",
  "name": "Payment",
  "fields": [
    {"name": "amount",   "type": "int"},
    {"name": "order_id", "type": "string"}
  ]
}

# New schema (v2) — backward-compatible: new field has a default
new_schema = {
  "type": "record",
  "name": "Payment",
  "fields": [
    {"name": "amount",   "type": "int"},
    {"name": "order_id", "type": "string"},
    {"name": "currency", "type": "string", "default": "USD"}  # default required
  ]
}
# New reader decoding old data: currency field → 'USD' (from default)
# NOT backward-compatible: adding a field WITHOUT a default

// Forward-compatible Protobuf schema evolution
// v1: original schema
message Payment {
  string order_id = 1;
  int32  amount   = 2;
}

// v2: new producer adds a field (forward-compatible)
message Payment {
  string order_id = 1;
  int32  amount   = 2;
  string currency = 3;  // NEW: old consumers skip tag 3 safely
}

// Old consumer (knows only v1) decoding v2 data:
// - Reads tag 1 (order_id): known, decoded
// - Reads tag 2 (amount):   known, decoded
// - Reads tag 3 (currency): UNKNOWN, skipped using wire type
// → No error; no data corruption
